files.a.ts:
// Reported by bun lint, not by oxlint: the second `?.` is needed,
// because `[1]` is `string | undefined` under noUncheckedIndexedAccess.
export function reported(s: string | undefined): string {
  return s?.split('/')[1]?.trim() ?? ''
}

// Same thing without the first `?.`: not reported (correct).
export function notReported(s: string): string {
  return s.split('/')[1]?.trim() ?? ''
}

